import{_ as t,c as a,o,ah as i}from"./chunks/framework.DaDXF32t.js";const h=JSON.parse('{"title":"Plugin system, API v1","description":"","frontmatter":{},"headers":[],"relativePath":"PLUGIN_SYSTEM.md","filePath":"PLUGIN_SYSTEM.md","lastUpdated":1793898957000}'),n={name:"PLUGIN_SYSTEM.md"};function s(d,e,r,c,l,p){return o(),a("div",null,e[0]||(e[0]=[i(`<h1 id="plugin-system-api-v1" tabindex="-1">Plugin system, API v1 <a class="header-anchor" href="#plugin-system-api-v1" aria-label="Permalink to “Plugin system, API v1”">​</a></h1><p>The service owns plugin discovery, profile settings and jobs. Desktop, Android and WebUI use the same authenticated trigger commands and declarative interface. A plugin never supplies executable frontend JavaScript, HTML, Qt widgets or CSS. The host renders its names, schemas and results with the application&#39;s own components and theme.</p><p>The mechanisms in <a href="https://github.com/pur1fying/blue_archive_auto_script/pull/583" target="_blank" rel="noreferrer">upstream PR 583</a> informed this design. Its Qt UI and the UI changes in <a href="https://github.com/sakurairsora/blue_archive_auto_script/pull/2" target="_blank" rel="noreferrer">PR 2</a> are not part of this implementation. The old five tools are not silently imported or registered as compatible v1 extensions.</p><h2 id="package-and-compatibility" tabindex="-1">Package and compatibility <a class="header-anchor" href="#package-and-compatibility" aria-label="Permalink to “Package and compatibility”">​</a></h2><p>A package contains <code>plugin.json</code> at its root and, for computation, ordinary Python source files. Bundled packages live under <code>service/plugins/bundled/&lt;id&gt;/</code>. User packages live under <code>plugins/&lt;id&gt;/</code>, outside the tracked source and outside other plugins&#39; configuration namespaces. The client can upload a local ZIP after authentication; no pip commands, installation hooks or arbitrary download URLs are run.</p><p><code>schema_version</code> describes the manifest format, <code>api_version</code> describes the host contract, and <code>version</code> is the plugin&#39;s own version. All three are separate. API v1 accepts schema/API integer <code>1</code>; incompatible versions are reported in the catalog. A stable, lowercase plugin ID may use namespaced dots, underscores or hyphens. IDs are never paths. Duplicate IDs cannot replace a bundled plugin or another installed plugin.</p><p>A computation entry point uses <code>module:function</code> syntax, for example <code>main:run</code>:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(context, inputs):</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Both arguments are plain JSON values. No service objects or auth data.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    prefix </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> context[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;settings&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;prefix&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: prefix </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> inputs[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]}</span></span></code></pre></div><p>The context contains <code>api_version</code>, <code>plugin_id</code>, <code>config_id</code> and the validated settings snapshot. It does not contain the login Key, session keys, core runtime, arbitrary configuration files or a device object. Return JSON-compatible values only; invalid, non-finite or excessively large output fails the job. Standard output is a worker protocol, not a UI rendering surface.</p><h2 id="manifest" tabindex="-1">Manifest <a class="header-anchor" href="#manifest" aria-label="Permalink to “Manifest”">​</a></h2><p>The required fields are <code>schema_version</code>, <code>api_version</code>, <code>id</code>, <code>version</code>, <code>name</code>, <code>description</code>, <code>permissions</code>, <code>settings_schema</code> and <code>actions</code>. Names and descriptions may be strings or locale maps such as <code>{&quot;en&quot;: &quot;Notes&quot;, &quot;zh&quot;: &quot;笔记&quot;}</code>. Clients use the selected language, then English, then an available translation.</p><p>An action has a stable <code>id</code>, localized <code>name</code>, optional description, an <code>execution</code> kind and an <code>input_schema</code>. An optional closed <code>output_schema</code> validates its result before publication. A <code>compute</code> action declares <code>entrypoint: &quot;main:run&quot;</code> and the <code>compute</code> permission. It executes in a separate, terminable Python process. A <code>device_task</code> action declares a host-supported <code>task_name</code> and the <code>device.tasks</code> permission. It has no Python entry point and cannot introduce an arbitrary core function name.</p><p>Settings and action inputs use a deliberately restricted JSON Schema subset: object properties, required keys and <code>additionalProperties: false</code>; bounded arrays with an item schema; strings, booleans, numbers and integers; defaults, enums, numeric bounds, titles and descriptions. Unsupported schema keywords or versions are rejected instead of silently interpreted with different semantics. The service validates every write and run; client-side validation only improves feedback.</p><p>An optional <code>contributions.home</code> array contains <code>{id, title, description?, action_id}</code> entries. Each entry references a declared action. The host may show a shortcut for an enabled plugin; opening it does not automatically execute the action. The manifest cannot inject arbitrary UI or override an existing application route. New execution kinds, permissions, schema features and contribution types require explicit host capability negotiation before use.</p><h2 id="bundled-automation-capability" tabindex="-1">Bundled automation capability <a class="header-anchor" href="#bundled-automation-capability" aria-label="Permalink to “Bundled automation capability”">​</a></h2><p>Hosts advertising <code>host.automation.v1</code> also accept <code>execution: &quot;host_automation&quot;</code> for a closed list of shipped tool/action pairs. These actions require <code>device.tasks</code> and declare neither an entry point nor a task name. External ZIPs cannot request this execution mode, even by copying a bundled ID. The host dispatches its own adapter, never Python loaded from the plugin package into the device process.</p><p><code>baas.auto-push</code> provides independent normal/hard mission lists, story episodes, activity actions and formation attributes. Its <code>current_stage</code> and <code>current_story</code> actions recognize supported screens and stop on unknown pages. Temporary task overrides are restored on success, failure and cancellation, while actual inventory updates remain persistent.</p><p><code>baas.hoard-ap</code> provides three actions: <code>plan</code> is a pure forecast, optionally accepting a <code>mailbox_snapshot</code>; <code>scan_mail</code> reads a fresh anonymous mailbox inventory without claiming rewards or requiring a target date; <code>start</code> rescans the device and executes the plan. Both device actions use the profile&#39;s exclusive runtime ownership gate, shared with the scheduler and other device tasks. Another task receives <code>already-running</code>/<code>DEVICE_BUSY</code>; scanning is read-only but still cannot race device automation. Starting owns the profile until completion or cancellation, with a maximum seven-day deadline. Long timelines do not occupy a compute-worker slot. Backend restart requires the user to replan and start again.</p><p>Hoarding results distinguish <code>available_at_target</code> from the projected remaining <code>summary</code>, and <code>inventory</code> separates verified mail from user-entered estimates and forecast source deliveries. The timeline tracks natural recovery caps, cafe capacity, server-day resets, already purchased AP and mail deadlines. A caller-provided snapshot supports forecasting; it never authorizes a device claim. Execution reads fresh character AP and the complete mailbox, and replans from those observations. AP purchases using pyroxene remain manual: a plan containing them reports <code>executable: false</code> and <code>PREMIUM_PURCHASES_ARE_MANUAL</code>, and <code>start</code> rejects it before claiming a source.</p><p>The verified mailbox/source adapters currently support the CN landscape layout, normalized to 1280×720; an unsupported server or uncertain recognition stops execution. Mail scanning verifies the AP icon, amount, received date, anonymous identity and individual claim button, and traverses the full unclaimed list against its displayed count. Equal-amount and identical letters retain their multiplicity. Visual stabilization is bounded; a count change or cancellation stops it.</p><p>Letters are indivisible. The executor creates headroom for a whole parcel, rescans and relocates it, clicks its individual button, then verifies the exact character-AP increase and complete mailbox multiset with only that letter removed. It never uses collect-all or splits a parcel to fit AP 999. Stale locators are not reused. Clearing AP uses the configured host route and requires an observed AP decrease.</p><p>Source collection requires an observed amount and a recognized source-state receipt, followed by character-AP and full-mailbox verification. Daily collection verifies the selected daily tab and claims individual AP cards; it does not claim weekly rewards or use the global reward button. Club sign-in delivers its AP through mail and is now executable when that source receipt and new whole parcel are verified. Overflow can also be verified at AP 999: direct AP gain plus new AP-mail amounts must equal the source receipt, and unrelated or missing mail stops execution. A capped counter, an arbitrary new letter or a legacy task&#39;s boolean return alone is insufficient proof.</p><p>Expiry is an interval, not a newly granted lifetime. Parcels carry conservative <code>expires_at</code>/<code>expires_before</code> bounds and <code>expiry_precision</code> (<code>day</code>, <code>hour</code>, <code>minute</code>, <code>second</code> or <code>under-hour</code>). A first “under one hour” observation has an immediate lower bound. During an execution, matching retained parcel copies keep the earlier observed deadline across rescans; independent scans and backend restarts do not share a persistent deadline cache. Forecast overflow lifetimes do not become execution deadlines; fresh source mail is read from the game.</p><p>The closed <code>scan_mail</code> result contains <code>complete</code>, <code>observed_at</code>, <code>mailbox_count</code>, <code>parcels</code>, <code>total_ap</code>, <code>fingerprint</code> and verified <code>character_ap</code>, plus result-kind fields. Public parcels contain <code>id</code>, <code>amount</code>, expiry bounds/precision, <code>received_at</code> and <code>occurrence</code>. Compact 32-character digest locators keep all 200 letters within the 64 KiB result limit; full digests and non-AP rows remain internal. Inventory is never truncated. Bounded history reports its total, offset and truncation status. Mail titles, senders, raw OCR text and screenshots stay outside the DTO and mail-recognition logs.</p><p>Anonymous CN live verification covered one three-star normal 28-2 sweep (one attempt, AP 999→989), one selected AP10 letter (AP 989→999, mailbox 4→3 with only that letter removed), and the daily-login AP100 reward at AP 999 (mailbox 3→4, AP-mail inventory 10→110, character AP unchanged). The new letter&#39;s displayed 23-hour expiry was retained as a conservative 22–24-hour interval. No pyroxene or JJC currency was spent. These observations verify those paths rather than asserting a universal overflow policy or exact lifetime for every reward source.</p><p>String schemas may declare <code>format: &quot;date-time&quot;</code> as a rendering hint. The client edits local date/time and sends an ISO 8601 instant with an explicit time zone. The hoarding tool uses its separate <code>server_utc_offset_minutes</code> and <code>reset_hour</code> for game-day boundaries, so a browser sending UTC does not shift the reset time. Empty initial values remain editable; the automation adapter validates required dates, time zones and the bounded planning horizon. Other format names and nonstring formats are rejected.</p><h2 id="authenticated-commands" tabindex="-1">Authenticated commands <a class="header-anchor" href="#authenticated-commands" aria-label="Permalink to “Authenticated commands”">​</a></h2><p>All commands use the existing <code>CommandMessage</code> envelope on the authenticated trigger channel. A successful response retains <code>status: &quot;ok&quot;</code> and returns the following <code>data</code>. Errors retain <code>status: &quot;error&quot;</code>, a stable <code>code</code> and a human-readable <code>error</code> string. There is no unauthenticated plugin HTTP endpoint.</p><table tabindex="0"><thead><tr><th>Command</th><th>Scope and payload</th><th>Result</th></tr></thead><tbody><tr><td><code>get_plugin_catalog</code></td><td>Optional <code>config_id</code></td><td><code>{api_version: 1, capabilities, plugins, errors}</code></td></tr><tr><td><code>get_plugin_settings</code></td><td><code>config_id</code>, <code>{plugin_id}</code></td><td><code>{plugin_id, config_id, revision, values}</code></td></tr><tr><td><code>update_plugin_settings</code></td><td><code>config_id</code>, <code>{plugin_id, revision, values}</code></td><td>Updated settings and revision</td></tr><tr><td><code>set_plugin_enabled</code></td><td><code>config_id</code>, <code>{plugin_id, enabled, trust_code?}</code></td><td>Plugin descriptor</td></tr><tr><td><code>run_plugin_action</code></td><td><code>config_id</code>, <code>{plugin_id, action_id, input, request_id}</code></td><td>Job snapshot</td></tr><tr><td><code>get_plugin_job</code></td><td><code>config_id</code>, <code>{job_id}</code></td><td>Job snapshot</td></tr><tr><td><code>cancel_plugin_job</code></td><td><code>config_id</code>, <code>{job_id}</code></td><td>Job snapshot</td></tr><tr><td><code>install_plugin</code></td><td>Binary ZIP upload with <code>{binary: true, filename?}</code></td><td>Installed descriptor</td></tr><tr><td><code>uninstall_plugin</code></td><td><code>{plugin_id}</code></td><td>Removal result</td></tr></tbody></table><p>A descriptor includes the manifest and <code>source</code>, <code>enabled</code>, <code>trusted</code>, <code>state</code>, and an optional structured error. The catalog can be read without selecting a profile, but still requires an authenticated connection. Profile-dependent operations require a real existing configuration ID. Old services return an unsupported-command error, which clients present as an upgrade requirement.</p><h2 id="settings-and-lifecycle" tabindex="-1">Settings and lifecycle <a class="header-anchor" href="#settings-and-lifecycle" aria-label="Permalink to “Settings and lifecycle”">​</a></h2><p>Settings are stored in the profile&#39;s separate <code>plugins.json</code> namespace. They are not appended to <code>ConfigSet</code> attributes, global defaults, <code>setup.toml</code> or <code>service_auth.json</code>. Atomic writes and monotonically increasing revisions prevent two clients from silently overwriting each other. On <code>REVISION_CONFLICT</code>, reload and explicitly reapply edits. Invalid JSON is preserved and reported rather than overwritten with empty defaults. Copy/export/import operations preserve optional plugin settings with the profile; import clears code trust and enablement.</p><p>Catalog discovery parses bounded JSON only. Disabled external plugins are not imported. Installing an external package leaves it disabled. Enabling external Python requires an explicit <code>trust_code: true</code> decision; trust is tied to the installed package, not merely its display name. Python plugins are trusted backend code, <strong>not a security sandbox</strong>. A child process supplies cancellation and failure isolation; it does not revoke operating-system access to files or the network. Install only code you trust.</p><p>Jobs report <code>queued</code>, <code>running</code>, <code>succeeded</code>, <code>failed</code> or <code>cancelled</code>, with identity, timestamps, optional JSON result and a structured error. A <code>request_id</code> deduplicates retries within the service&#39;s retained job window. Polling and cancellation are profile-scoped; another profile cannot retrieve or cancel a job by guessing its ID. Completed jobs and output have bounded retention. Computations are concurrency-limited and terminate on timeout/cancel/shutdown. Device tasks use the existing profile runtime lock, initialization, logging, Android display guard and stop lifecycle. A task already running in that profile is never replaced by a plugin action.</p><p>Running jobs prevent uninstall or unsafe enable/disable changes. Uninstall removes installed code and its registration, not unrelated profiles or application credentials. Bundled plugins cannot be removed. There is no automatic plugin update or dependency installation in v1.</p><p>The initial limits are 10 MiB per uploaded ZIP, 32 MiB unpacked, 256 package files/nodes, 16 directory levels, 100 discovered packages, two concurrent workers, eight active jobs and 128 retained jobs. Inputs/settings/results are bounded JSON; results are limited to 64 KiB. Computation timeouts default to 30 seconds and may be declared from 0.1 to 120 seconds. Device tasks default to 30 minutes, with a maximum of one hour. Linux/macOS use an owned process group; Windows assigns each worker to a Job Object before it receives executable input. Cleanup is a runtime responsibility on every supported transport.</p><p>Android&#39;s embedded Chaquopy runtime uses two private native service processes instead of launching <code>sys.executable</code> or forking the JVM. They execute the same standard-library worker protocol through bounded private files. Native leases bind cancellation to a slot, random token and process identity; an old cancellation cannot stop a replacement job. Each service owns its process group, watches its backend owner and has an independent hard deadline. Worker services are not exported or automatically restarted. An older Android client reports <code>ANDROID_WORKER_UNAVAILABLE</code> and needs updating; desktop and WebUI workers keep their existing launch path.</p><h2 id="included-plugins" tabindex="-1">Included plugins <a class="header-anchor" href="#included-plugins" aria-label="Permalink to “Included plugins”">​</a></h2><p>The five bundled tools use the application&#39;s own theme and components: <code>baas.hoard-ap</code> supplies forecasting, mailbox scanning and verified execution; <code>baas.auto-push</code> supplies supported mission/story automation; <code>baas.equipment-planner</code> supplies equipment planning, estimates, eleph calculations and catalog lookup; <code>baas.inventory-calculator</code> solves inventory calculations; and <code>baas.home-editor</code> stores per-profile home-section visibility and order. The home editor has no executable actions. Device automation starts only when the user explicitly runs an action; opening a shortcut or editing settings does not start it.</p><p>New solvers, policy hooks or task adapters must declare compatible APIs and capabilities. Resource operations must specify verification, failure and cancellation behavior; an uncertain receipt stops execution rather than silently continuing or replaying a potentially completed claim.</p>`,40)]))}const m=t(n,[["render",s]]);export{h as __pageData,m as default};
